 */
function bp_guide_catalog(): array
{
    return ['features'=>['label'=>'Mogućnosti','kicker'=>'JEDINSTVENI BRENDIGO PAY','intro'=>'Funkcionalnosti povezane s istim korisničkim računom na webu, WordPressu i Androidu.','pages'=>['payment-links'=>['title'=>'Platni linkovi','summary'=>'Kreirajte poveznicu za jasno definiranu uslugu ili proizvod i dijelite je s kupcem.','sections'=>[['title'=>'Za što se koriste','items'=>['Jednokratne testne uplate za usluge, rezervacije, edukacije i proizvode.','Svaki link ima naziv, opis, točan iznos u EUR, status i povezanu licenciranu stranicu.','Kupac dobiva zasebnu stranicu s informacijama i izborom dostupnog testnog pružatelja.']],['title'=>'Upravljanje','items'=>['U korisničkom panelu otvorite Platni linkovi i odaberite Kreiraj link.','Poveznicu možete kopirati ili otvoriti, uključiti i isključiti.','Na Androidu su dostupni isti linkovi i opcije njihove aktivacije.']],['title'=>'Sigurnost naplate','items'=>['Onemogućeni linkovi ne smiju prihvaćati novu uplatu.','Potvrdu plaćanja daje poslužiteljska provjera pružatelja; otvaranje završne stranice nije dokaz uplate.']]],'external'=>[]],'qr-codes'=>['title'=>'QR kodovi','summary'=>'Jednostavno dijeljenje postojećih naplatnih poveznica putem QR koda.','sections'=>[['title'=>'Primjena','items'=>['Kupac skenira QR kod mobilnim uređajem i otvara istu testnu naplatnu stranicu.','QR prikaz možete umetnuti u WordPress blok na stranicu s uslugom ili ponudom.']],['title'=>'Izrada','items'=>['Registrirajte i aktivirajte licenciranu stranicu.','Kreirajte platni link pa uključite QR prikaz u Gutenberg postavkama bloka.','Prije objave provjerite da QR vodi na ispravnu HTTPS adresu i točan iznos.']],['title'=>'Važna razlika','items'=>['QR kod s poveznicom nije sam po sebi bankovni nalog ni dokaz uplate.','Za bankovne uplate koristite posebno konfiguriranu WooCommerce bankovnu metodu i ručnu provjeru priljeva.']]],'external'=>[]],'woocommerce'=>['title'=>'WooCommerce naplata','summary'=>'Povežite WooCommerce trgovinu s korisničkim panelom i vlastitim testnim pružateljima.','sections'=>[['title'=>'Podržani prikazi','items'=>['Podržani su klasični WooCommerce checkout i WooCommerce Checkout Blocks.','Na blagajni se prikazuju samo testne opcije koje imaju važeću sinkronizaciju licence.']],['title'=>'Životni ciklus','items'=>['Narudžba ostaje na čekanju dok platni pružatelj ne potvrdi događaj.','Povrat s platne stranice sam po sebi ne mijenja narudžbu u plaćenu.']],['title'=>'Pouzdanost','items'=>['U WordPress postavkama pratite status licence i posljednje sinkronizacije.','Ako je veza zastarjela, dodatak ne smije nuditi Brendigo Pay kao dostupan način naplate.']]],'external'=>[]],'wordpress'=>['title'=>'WordPress Gutenberg','summary'=>'Ugrađeni blokovi za naplatu bez potrebe za WooCommerce trgovinom.','sections'=>[['title'=>'Komponente','items'=>['Naplatna kartica, gumb i poveznica dostupni su u uređivaču blokova.','Možete uključiti QR prikaz i prilagoditi tekst gumba gdje su opcije dostupne.']],['title'=>'Umetanje','items'=>['Instalirajte dodatak i aktivirajte licencu za odgovarajuću domenu.','U Gutenberg editoru dodajte blok Brendigo Pay – Naplata.','Odaberite postojeći platni link ili unesite njegov ID i spremite stranicu.']],['title'=>'Provjera','items'=>['Testirajte prikaz na telefonu i računalu.','Provjerite da se iznos i status preuzimaju iz istog korisničkog računa.']]],'external'=>[]],'analytics'=>['title'=>'Transakcije i izvještaji','summary'=>'Jedan pregled testne aktivnosti s filtriranjem prema vlasniku računa.','sections'=>[['title'=>'Korisnički pogled','items'=>['Pregled ukupnih potvrđenih testnih uplata, broja transakcija i statusa.','U odjeljku Transakcije pratite iznos, datum, izvor i stanje pojedine transakcije.']],['title'=>'Statusi','items'=>['Uspješno označava potvrđenu testnu uplatu.','Na čekanju i U obradi nisu isto što i konačna naplata.','Neuspješno označava testni pokušaj koji nije potvrđen.']],['title'=>'Prava pristupa','items'=>['Trgovac vidi samo vlastite podatke.','Administrator platforme pristupa zasebnom administracijskom panelu, uz dodatne ovlasti.']]],'external'=>[]],'android'=>['title'=>'Android korisnički panel','summary'=>'Pogledajte svoje transakcije, linkove i licence u nativnoj Android aplikaciji.','sections'=>[['title'=>'Jedan račun','items'=>['Registrirajte se na webu ili u aplikaciji i prijavite se istom e-adresom i lozinkom.','U aplikaciji birate jedan od plaćenih paketa; samo registracija ne omogućuje naplatu.']],['title'=>'Upravljanje','items'=>['Pregledajte transakcije i metrike svog računa.','Kreirajte i uključujte testne linkove, pratite licence i status povezanih testnih pružatelja.']],['title'=>'Instalacija','items'=>['Aplikacija zahtijeva HTTPS adresu vaše Brendigo Pay platforme.','Razvojni APK služi za isprobavanje; službena Play distribucija zahtijeva dodatno potpisivanje i odobrenja.']]],'external'=>[]],'licensing'=>['title'=>'Pretplate i licence','summary'=>'Tri plaćena paketa i jasno ograničenje instalacija po domeni.','sections'=>[['title'=>'Paketi','items'=>['Start: 19,90 € mjesečno, jedna domena.','Business: 49,90 € mjesečno, pet domena.','Pro: 99,90 € mjesečno, do 25 domena.']],['title'=>'Aktivacija','items'=>['Odabir paketa pri registraciji nije potvrda uplate.','Nakon provjere naplate operater aktivira paket i datum isteka.','Licenca se izdaje za konkretnu HTTPS domenu i provjerava pri instalaciji dodatka.']],['title'=>'Promjene','items'=>['U korisničkom panelu pregledajte iskorištene domene.','Nakon rotacije licence stari ključ prestaje vrijediti.','Neiskorišteno mjesto oslobađa se uklanjanjem domene iz vlastitog računa.']]],'external'=>[]]]],'integrations'=>['label'=>'Integracije','kicker'=>'PLATNI I WEB PARTNERI','intro'=>'Praktične upute za postojeće sandbox veze i transparentni status budućih integracija.','pages'=>['stripe'=>['title'=>'Stripe TEST','summary'=>'Stripe Checkout testni adapter za povezivanje vlastitog računa.','sections'=>[['title'=>'Prije početka','items'=>['Otvorite vlastiti Stripe račun i uključite testni način rada.','Upoznajte se sa Stripe Checkoutom i pravilima webhook događaja.']],['title'=>'Povezivanje','items'=>['U web panelu otvorite Postavke i Stripe TEST.','Podesite testno povezivanje računa i upišite potrebne testne vjerodajnice u zaštićeno polje.','Provjerite status konfiguracije u korisničkom panelu; Android prikazuje povezano testno stanje.']],['title'=>'Testiranje','items'=>['Napravite platni link ili WooCommerce narudžbu i pokrenite testnu uplatu.','Provjerite prihvat i provjeru webhook potvrde prije statusa Uspješno.','Nema podrške za stvarne uplate bez produkcijskog onboardinga i testova.']]],'external'=>[['Stripe Checkout dokumentacija','https://docs.stripe.com/payments/checkout']]],'paypal'=>['title'=>'PayPal Sandbox','summary'=>'PayPal testni račun za plaćanje putem vanjskog PayPal okruženja.','sections'=>[['title'=>'Preduvjeti','items'=>['Otvorite PayPal Developer račun i pripremite Sandbox Business i testni kupčev račun.','Za aplikaciju nabavite Sandbox Client ID i Secret, te Webhook ID ako ga koristite.']],['title'=>'Povezivanje','items'=>['Na webu otvorite Postavke → PayPal Sandbox.','Unesite testne podatke i podesite webhook prema adresi koju panel prikazuje za vaš račun.','Provjerite testni status nakon spremanja.']],['title'=>'Potvrda uplate','items'=>['Napravite testnu narudžbu, otvorite PayPal hosted checkout i obavite testni capture.','Status konačne uplate treba potvrditi webhook/API poziv; samo povrat u preglednik nije dovoljan.']]],'external'=>[['PayPal službena integracija','https://developer.paypal.com/platforms/checkout/standard/integrate']]],'revolut'=>['title'=>'Revolut Merchant Sandbox','summary'=>'Testni Revolut Merchant API s provjerom završnog statusa uplate.','sections'=>[['title'=>'Preduvjeti','items'=>['Trgovac treba Revolut Business/Merchant pristup i odobreno testno okruženje.','Prije povezivanja pregledajte odgovarajuću verziju službenog Merchant API-ja.']],['title'=>'Podešavanje','items'=>['U web panelu otvorite Postavke → Revolut Sandbox.','Postavite testne vjerodajnice i webhook prema prikazanoj uputi.']],['title'=>'Provjera','items'=>['Koristite testnu uplatu i provjerite status narudžbe nakon poslužiteljske potvrde.','Konačni ORDER_COMPLETED događaj razlikuje se od samog otvaranja završne stranice.']]],'external'=>[['Revolut Merchant API','https://developer.revolut.com/docs/api/merchant']]],'wordpress'=>['title'=>'WordPress dodatak','summary'=>'Jedna Brendigo Pay instalacija povezana s točno određenom domenom.','sections'=>[['title'=>'Priprema','items'=>['Na webu otvorite račun i pričekajte potvrdu plaćenog paketa.','U korisničkom panelu unesite HTTPS adresu na kojoj radi WordPress.']],['title'=>'Instalacija','items'=>['U WordPressu otvorite Dodaci → Dodaj novi → Prenesi dodatak.','Instalirajte ZIP Brendigo Pay i kliknite Aktiviraj.','U postavkama dodatka spremite HTTPS adresu web-platforme.']],['title'=>'Aktivacija','items'=>['Unesite ključ licence iz vlastitog korisničkog panela.','Kliknite Aktiviraj licenciju i poveži, zatim Sinkroniziraj sada.','U webu i WordPressu provjerite istu domenu, status i verziju dodatka.']]],'external'=>[]],'woocommerce'=>['title'=>'WooCommerce Checkout','summary'=>'Povezivanje Brendigo Pay testnih opcija s WooCommerce blagajnom.','sections'=>[['title'=>'Provjera','items'=>['WooCommerce mora biti aktiviran i ažuriran; Brendigo Pay dodatak mora imati potvrđenu licencu.','Na webu pripremite barem jedan kompatibilan sandbox pružatelj.']],['title'=>'Uključivanje','items'=>['Otvorite WooCommerce → Postavke → Plaćanja.','Omogućite Brendigo Pay Sandbox i odaberite prikladne testne opcije.','Provjerite blagajnu na telefonu i računalu te s blokovskom i klasičnom naplatom.']],['title'=>'Rješavanje poteškoća','items'=>['Ako je sinkronizacija nevažeća, blagajna namjerno ne prikazuje Brendigo Pay.','Ako se pojavila kritična WordPress greška, ažurirajte dodatak na izdanje 0.8.6 ili novije i pregledajte dnevnik grešaka.']]],'external'=>[['WooCommerce BACS upute','https://woocommerce.com/document/bacs/']]],'bank-transfer'=>['title'=>'Bankovna uplata i pouzeće','summary'=>'Hrvatske i SEPA uplate koje se potvrđuju ručno u WooCommerceu.','sections'=>[['title'=>'Bankovna uplata','items'=>['U WooCommerce → Postavke → Plaćanja omogućite ugrađenu metodu Bankovna uplata (BACS).','Upišite poslovni IBAN i upute za kupca prema uputama vaše banke.','Narudžba ostaje Na čekanju (On hold) dok ne provjerite priljev.']],['title'=>'Pouzeće','items'=>['WooCommerce uključuje zaseban način plaćanja pouzećem.','Naplata se potvrđuje prilikom isporuke, a ne preko Stripe/PayPal/Revolut adaptera.']],['title'=>'Ograničenja','items'=>['Bankovni nalog i QR kod sami po sebi nisu dokaz da je novac primljen.','Ne označavajte ručne uplate automatski kao uspješne.']]],'external'=>[['WooCommerce bankovni transfer','https://woocommerce.com/document/bacs/']]],'monri'=>['title'=>'Monri WebPay — planirano','summary'=>'Hrvatski/regionalni pružatelj koji još nije aktivan u Brendigo Pay naplati.','sections'=>[['title'=>'Status','items'=>['Monri WebPay nije ponuđen kao aktivni checkout adapter u ovom izdanju.','Službene mogućnosti obuhvaćaju Redirect, Components i Lightbox integraciju.']],['title'=>'Što je potrebno','items'=>['Odobreni merchant račun i testni pristup Monri sučelju.','Odabrani dokumentirani protokol, potpisivanje zahtjeva, obrada rezultata i provjera identiteta transakcije.']],['title'=>'Prije aktivacije','items'=>['Proći pozitivne i negativne testove, ponovljene webhooks i povrate.','Prikazati status Aktivno tek nakon završne provjere.']]],'external'=>[['Monri WebPay dokumentacija','https://ipg.monri.com/hr/documentation']]],'corvuspay'=>['title'=>'CorvusPay — planirano','summary'=>'Domaći pružatelj predviđen za daljnji razvoj, bez neprovjerene aktivacije.','sections'=>[['title'=>'Status','items'=>['CorvusPay nije ugrađen kao funkcionalan platni adapter.','Ne prikazujemo ga na naplatnoj stranici dok merchant testiranje nije dovršeno.']],['title'=>'Preduvjeti','items'=>['Za integraciju su potrebni službena odobrena merchant okolina i aktualne tehničke upute.','Potpisivanje, odgovori, poništenja, povrati i obavijesti moraju se testirati na testnom računu.']],['title'=>'Kriterij završetka','items'=>['Potvrda testne naplate, negativni scenariji i ispravno ažuriranje WooCommerce narudžbe.','Formalna dozvola i dokumentacija za produkcijsko puštanje.']]],'external'=>[['CorvusPay integracijske upute','https://github.com/corvuspay/corvus-frame-integration-doc']]]]],'docs'=>['label'=>'Dokumentacija','kicker'=>'CENTAR ZA POMOĆ','intro'=>'Detaljne korisničke upute za konfiguraciju, povezivanje, svakodnevni rad i provjeru testnih uplata. Ne zahtijevaju pristup internim sustavima.','pages'=>['quickstart'=>['title'=>'Brzi početak','summary'=>'Od registracije do prve testne naplatne poveznice — redom i bez nepotrebnih koraka.','sections'=>[['title'=>'1. Otvorite poslovni račun','items'=>['Na webu ili Androidu odaberite Registracija, unesite naziv, e-adresu i sigurnu lozinku.','Odaberite Start, Business ili Pro. Registracija sama po sebi ne aktivira pretplatu.','Pričekajte da operater provjeri uplatu i aktivira važeći paket.']],['title'=>'2. Povežite web-stranicu','items'=>['U korisničkom panelu otvorite Web-stranice i dodajte svoju punu HTTPS domenu.','Kopirajte izdanu licencu i instalirajte WordPress dodatak ako koristite WordPress.','U WordPress dodatku unesite URL platforme i licencu, aktivirajte i pokrenite sinkronizaciju.']],['title'=>'3. Povežite testnog pružatelja','items'=>['Na webu otvorite Postavke te pripremite Stripe TEST, PayPal Sandbox ili Revolut Sandbox račun.','Ne unosite produkcijske ključeve u sandbox.']],['title'=>'4. Napravite testnu uplatu','items'=>['Kreirajte link s nazivom, iznosom i domenom.','Otvorite naplatnu stranicu na testnom uređaju i odradite testnu kupnju.','U panelu potvrdite status transakcije; tek potvrda pružatelja znači Uspješno.']],['title'=>'5. Provjerite sinkronizaciju','items'=>['Na Androidu prijavite se istim računom i otvorite Pregled.','U WordPressu provjerite verziju i vrijeme posljednje sinkronizacije.','Pritom svaki račun vidi samo vlastite podatke.']]],'external'=>[]],'account'=>['title'=>'Korisnički račun i prijava','summary'=>'Kako rade registracija, prijava i prava pristupa na svim uređajima.','sections'=>[['title'=>'Registracija','items'=>['Na webu i Androidu zadajete isti identitet računa.','E-adresa mora biti jedinstvena, a lozinka imati najmanje 12 znakova.','Novi račun može se prijaviti odmah, ali nema aktivan paket bez potvrde naplate.']],['title'=>'Prijava na drugom uređaju','items'=>['Na Androidu unesite HTTPS URL vlastite platforme.','Prijavite se istom e-adresom i lozinkom kojima pristupate web-panelu.','Ako je sesija istekla, prijavite se ponovno; nemojte kopirati tuđe licencne ključeve.']],['title'=>'Vidljivost i ovlasti','items'=>['Običan korisnik ne može otvoriti administracijski panel.','Podaci o transakcijama, linkovima, domenama i integracijama prikazuju se samo vlasniku.']],['title'=>'Zaštita računa','items'=>['Nemojte dijeliti pristupne podatke ili licencni ključ.','Kada izgubite pristup računu, obratite se podršci; ne postoji nesigurna automatska zaobilaznica prijave.']]],'external'=>[]],'plans'=>['title'=>'Plaćeni paketi i obnova','summary'=>'Odabir paketa, granice licenci i što se događa nakon isteka.','sections'=>[['title'=>'Usporedba','items'=>['Start: do 1 domene za 19,90 € mjesečno.','Business: do 5 domena za 49,90 € mjesečno.','Pro: do 25 domena za 99,90 € mjesečno.','Nema besplatnog paketa.']],['title'=>'Aktivacija','items'=>['Odabrani paket označava zahtjev korisnika.','Korisnička registracija i pregled cijena nisu potvrda primitka novca.','Operater po provjeri stvarne uplate ručno aktivira rok valjanosti.']],['title'=>'Promjena i istek','items'=>['Kod isteka licence naplatne funkcije dodatka prestaju biti dostupne.','Izbrisana domena oslobađa jedno mjesto u paketu.','Za produljenje ili promjenu paketa kontaktirajte operatera dok automatska naplata pretplate nije dostupna.']]],'external'=>[]],'sites'=>['title'=>'Web-stranice i licencije','summary'=>'Registrirajte točnu domenu koja će koristiti vaš WordPress dodatak.','sections'=>[['title'=>'Dodavanje domene','items'=>['U web panelu otvorite Web-stranice.','Unesite adresu s HTTPS protokolom i bez proizvoljnih dodatnih putanja.','Za svaku domenu izdaje se zasebna licenca unutar limita odabranog paketa.']],['title'=>'Povezivanje dodatka','items'=>['Instalirajte isti Brendigo Pay plugin na navedenoj domeni.','Unesite adresu platforme i upravo izdani licencni ključ.','Potvrdite aktivaciju i provjerite sinkronizirani status u oba panela.']],['title'=>'Rotacija','items'=>['Ako je ključ nevažeći ili sumnjate na neovlašten pristup, u panelu zatražite novi.','Stari ključ više nije važeći; ažurirajte postavke WordPressa.']],['title'=>'Uklanjanje','items'=>['Uklonite domenu samo ako se dodatak na njoj više neće koristiti.','Nakon uklanjanja mjesto u paketu ponovno postaje dostupno.']]],'external'=>[]],'wordpress'=>['title'=>'Instalacija WordPress dodatka','summary'=>'Od preuzimanja ZIP-a do aktivacije licence i Gutenberg gumba.','sections'=>[['title'=>'Provjerite preduvjete','items'=>['WordPress mora imati administratorski pristup i HTTPS web-stranicu.','Paket na Brendigo Payu mora biti aktivan, a domena prethodno registrirana.']],['title'=>'Instalacija','items'=>['Otvorite Dodaci → Dodaj novi → Prenesi dodatak.','Odaberite ZIP iz posljednjeg GitHub izdanja i kliknite Instaliraj sada.','Aktivirajte dodatak i otvorite Brendigo Pay → Postavke.']],['title'=>'Licenca i status','items'=>['Spremite HTTPS adresu Brendigo Pay web-platforme.','Unesite licencu povezanu s točnom domenom i aktivirajte je.','Kliknite Sinkroniziraj sada i provjerite status.']],['title'=>'Prvi Gutenberg blok','items'=>['Otvorite željenu WordPress stranicu i dodajte Brendigo Pay – Naplata.','U bočnoj traci odaberite odgovarajući testni platni link, stil gumba i QR prikaz.','Objavite i pregledajte stranicu na različitim širinama zaslona.']]],'external'=>[]],'woocommerce'=>['title'=>'WooCommerce trgovina','summary'=>'Koraci konfiguracije i sigurno testiranje Classic i Blocks naplate.','sections'=>[['title'=>'Omogućite dodatak','items'=>['Instalirajte i aktivirajte WooCommerce i Brendigo Pay.','U WordPressu unesite i potvrdite domensku licencu.','U web panelu povežite testnog pružatelja.']],['title'=>'Uključite plaćanje','items'=>['Otvorite WooCommerce → Postavke → Plaćanja.','Uključite Brendigo Pay Sandbox te provjerite prikaz opcija na blagajni.','Isprobajte i Classic Checkout i Checkout Blocks ako ih trgovina koristi.']],['title'=>'Testna narudžba','items'=>['Kreirajte testnu košaricu, potvrdite kupca i odaberite pružatelja.','Prođite pozitivni test, odbijenu uplatu i napušteni checkout.','Naručeni proizvod ili digitalnu uslugu ne isporučujte na temelju samog povratnog URL-a.']],['title'=>'Problemi','items'=>['Ako metoda nije ponuđena, provjerite da je licenca aktivna i sinkronizirana u posljednja dva sata.','Provjerite da testni pružatelj ima ispravno spremljene postavke.','Kod kritične WordPress greške ažurirajte plugin bez brisanja postojećih postavki.']]],'external'=>[]],'payment-links'=>['title'=>'Kreiranje i dijeljenje platnih linkova','summary'=>'Odaberite pravilnu domenu, naziv usluge i iznos.','sections'=>[['title'=>'Kreiranje','items'=>['Otvorite Korisnički panel → Platni linkovi i kliknite Kreiraj link.','Odaberite povezanu domenu i upišite naziv, opis i pozitivan iznos u EUR.','Spremite i kopirajte poveznicu za testiranje.']],['title'=>'Dijeljenje','items'=>['Pošaljite HTTPS link e-poštom ili porukom.','U Gutenberg uređivaču umetnite karticu ili gumb; poveznica se može prikazati i kao QR kod.']],['title'=>'Upravljanje','items'=>['Onemogućite link kada ponuda više ne vrijedi.','Na Androidu su dostupni isti linkovi i isti statusi.','Ako je plaćeni paket ili domena neaktivna, link ne smije omogućiti naplatu.']]],'external'=>[]],'qr'=>['title'=>'QR prikaz naplatnog linka','summary'=>'Praktični koraci za mobilno plaćanje putem otvorene HTTPS poveznice.','sections'=>[['title'=>'Pripremite poveznicu','items'=>['Kreirajte odgovarajući platni link u web korisničkom panelu.','Provjerite testni iznos i naziv usluge.']],['title'=>'Prikažite QR','items'=>['U WordPress Gutenberg bloku uključite QR prikaz i željeni tekst.','Testirajte mobilnom kamerom i provjerite odredišnu adresu.']],['title'=>'Razlikujte vrste','items'=>['QR koji otvara checkout nije EPC/HUB3 bankovni nalog.','Prikaz uspješne stranice nije potvrda da je transakcija zaista završena.']]],'external'=>[]],'android'=>['title'=>'Android aplikacija','summary'=>'Prijava, registracija i pregled vlastitih testnih transakcija u džepu.','sections'=>[['title'=>'Prva prijava','items'=>['Instalirajte testni APK na podržani uređaj.','Unesite službenu HTTPS adresu web-platforme.','Prijavite se postojećim web računom ili registrirajte novi.']],['title'=>'Zasloni','items'=>['Pregled prikazuje testne metrike i povezane pružatelje.','Transakcije prikazuju samo zapise vlastitog računa.','Linkovi omogućuju pregled, kreiranje i uključivanje vlastitih linkova.','Web-stranice prikazuju povezane domene, licence i vrijeme sinkronizacije.']],['title'=>'Sigurnost i granice','items'=>['Izgubljena ili istekla sesija zahtijeva novu prijavu.','APK iz ovog izdanja služi za testiranje; objava na Google Playu traži zasebnu provjeru i potpisani AAB.']]],'external'=>[]],'providers'=>['title'=>'Postavljanje pružatelja','summary'=>'Kako pronaći vlastite testne račune i kada ih prikazati kao dostupne.','sections'=>[['title'=>'Odabir','items'=>['Dostupni sandbox putevi: Stripe, PayPal i Revolut.','Monri WebPay i CorvusPay su u planu, ne uključuju se prije provjerenih testova.']],['title'=>'Povezivanje','items'=>['Na webu otvorite Postavke i karticu odgovarajućeg pružatelja.','Pripremite vlastiti testni račun i slijedite upute za webhook.','Nakon povezivanja provjerite status na webu, Androidu i WordPressu.']],['title'=>'Provjera','items'=>['Pokrenite uspješan, neuspješan i prekinut testni checkout.','Nakon potvrde putem pružatelja provjerite odgovarajući status narudžbe.']]],'external'=>[]],'stripe'=>['title'=>'Stripe — koraci povezivanja','summary'=>'Korisnički vodič za povezivanje Stripe TEST računa.','sections'=>[['title'=>'Pripremite račun','items'=>['U Stripe nadzornoj ploči uključite Test mode.','Potvrdite da koristite testne, a ne produkcijske podatke.']],['title'=>'Konfigurirajte','items'=>['Na webu otvorite Postavke → Stripe TEST ili Stripe Connect TEST ako je omogućen.','Podesite odgovarajući testni webhook za svoj račun.']],['title'=>'Testirajte','items'=>['Otvorite testni link i dovršite primjer naplate na Stripe hosted checkoutu.','Provjerite da se status potvrđuje server-side događajem i da ponovljeni događaj ne mijenja naplatu dvaput.']]],'external'=>[['Stripe službeni vodič','https://docs.stripe.com/payments/checkout']]],'paypal'=>['title'=>'PayPal — koraci povezivanja','summary'=>'Korisnički vodič za PayPal Sandbox.','sections'=>[['title'=>'Priprema','items'=>['Otvorite PayPal Developer testnu aplikaciju i provjerite Business sandbox račun.','Pronađite Sandbox Client ID i Secret.']],['title'=>'Povezivanje','items'=>['Unesite testne podatke u Postavke → PayPal Sandbox na webu.','Registrirajte webhook prikazan u panelu i spremite njegov identifikator.']],['title'=>'Testiranje','items'=>['Pokrenite testnu kupnju s testnim PayPal kupcem.','Provjerite potvrđeni capture događaj i status transakcije.']]],'external'=>[['PayPal dokumentacija','https://developer.paypal.com/platforms/checkout/standard/integrate']]],'revolut'=>['title'=>'Revolut — koraci povezivanja','summary'=>'Korisnički vodič za Revolut Merchant Sandbox.','sections'=>[['title'=>'Priprema','items'=>['Provjerite da merchant račun podržava testno okruženje.','Pripremite odgovarajuću verziju dokumentacije Merchant API-ja.']],['title'=>'Povezivanje','items'=>['Na webu otvorite Postavke → Revolut Sandbox i unesite testne podatke.','Dodajte webhook za statusne promjene naloga.']],['title'=>'Provjera','items'=>['Pokrenite uspješan i odbijen testni checkout.','Ne smatrajte narudžbu plaćenom dok server ne potvrdi završni događaj.']]],'external'=>[['Revolut API','https://developer.revolut.com/docs/api/merchant']]],'transactions'=>['title'=>'Transakcije i statusi','summary'=>'Razumijevanje testne naplate i što smijete zaključiti iz statusa.','sections'=>[['title'=>'Pregled transakcija','items'=>['Otvorite Transakcije u web korisničkom panelu ili Androidu.','Pratite vrijeme, iznos, ID, status i izabranog pružatelja.']],['title'=>'Statusi','items'=>['Uspješno — završni događaj testnog pružatelja potvrđen.','Na čekanju ili U obradi — nije naplaćeno u konačnom smislu.','Neuspješno — pokušaj nije dovršen.']],['title'=>'Postupanje u slučaju razlike','items'=>['Provjerite transakciju u vlastitom testnom merchant računu.','Ako ne odgovara status u panelu, provjerite webhook ili dostupnost platforme; nemojte mijenjati narudžbu ručno bez potvrde.']]],'external'=>[]],'webhooks'=>['title'=>'Potvrda transakcije i obavijesti','summary'=>'Zašto su potvrde platnih pružatelja važne za točnost narudžbi.','sections'=>[['title'=>'Uloga webhooks','items'=>['Platni pružatelj šalje zasebnu obavijest nakon događaja naplate.','Brendigo Pay provjerava poruku i pripadajuću narudžbu prije ažuriranja statusa.']],['title'=>'Podešavanje','items'=>['U korisničkom panelu otvorite postavke odabranog sandbox pružatelja.','Prikažite i unesite ispravnu webhook adresu u panel pružatelja.','Odaberite službeno preporučene događaje za potvrdu naplate.']],['title'=>'Testiranje','items'=>['Pošaljite uspješan i neuspješan testni događaj i provjerite status.','Provjerite ponovljene događaje, vremenska kašnjenja i poništenja.']],['title'=>'Sigurnost','items'=>['Nije dovoljno da kupac samo otvori završnu stranicu.','Ne šaljite potpune vjerodajnice ili tajne izvan sigurnih postavki.']]],'external'=>[]],'security'=>['title'=>'Sigurnost i upravljanje pristupom','summary'=>'Smjernice za sigurniju instalaciju i rad.','sections'=>[['title'=>'Pristup','items'=>['Administratorske ovlasti i korisničke ovlasti moraju ostati odvojene.','Svaki trgovac vidi vlastite zapise, a WordPress instalacija povezuje se samo s dodijeljenom domenom.']],['title'=>'Sigurnost računa','items'=>['Koristite jedinstvenu dugu lozinku i HTTPS.','Ako sumnjate na kompromitiran pristup, odjavite sesije i rotirajte licencu.']],['title'=>'Kartični podaci','items'=>['Plaćanje karticom preusmjerava se pružatelju; nemojte tražiti kartične podatke u WordPress ili Brendigo Pay obrascima.']],['title'=>'Priprema za produkciju','items'=>['Prije stvarnog rada potrebni su završni testovi pružatelja, sigurnosti i pravne usklađenosti.']]],'external'=>[]],'troubleshooting'=>['title'=>'Rješavanje problema','summary'=>'Najčešći slučajevi kada se web, dodatak ili Android ne mogu povezati.','sections'=>[['title'=>'Prijava ne radi','items'=>['Provjerite e-adresu, lozinku i točan HTTPS URL platforme.','Ako je previše pokušaja prijave, pokušajte nakon isteka privremenog ograničenja.']],['title'=>'Licenca je odbijena','items'=>['Provjerite je li plaćeni paket aktivan i nije istekao.','U panelu usporedite točnu HTTPS domenu s instaliranom WordPress stranicom.','Ako je ključ rotiran, ponovno aktivirajte novu licencu.']],['title'=>'WooCommerce metoda nije prikazana','items'=>['U WordPress postavkama kliknite Sinkroniziraj sada.','Provjerite je li posljednja potvrda unutar dva sata i je li testni pružatelj konfiguriran.']],['title'=>'Kritična WordPress greška','items'=>['Instalirajte posljednji kompatibilni Brendigo Pay ZIP preko postojećeg dodatka bez brisanja postavki.','U WordPress recovery načinu pristupite administratoru i pregledajte točnu PHP grešku.','Ako se greška ponovi, spremite naziv datoteke i redak iz loga, bez javnog objavljivanja tajnih ključeva.']],['title'=>'Android ne može otvoriti panel','items'=>['Provjerite internet i ispravan HTTPS certifikat.','Ažurirajte aplikaciju i ponovno se prijavite ako je sesija istekla.']]],'external'=>[]],'faq'=>['title'=>'Često postavljana pitanja','summary'=>'Brzi odgovori za korisnike i administratore.','sections'=>[['title'=>'Mogu li imati besplatan paket?','items'=>['Ne. Dostupni su samo Start, Business i Pro kao plaćeni paketi.']],['title'=>'Mogu li na Android s istim web podacima?','items'=>['Da. Web i Android dijele isti korisnički račun.']],['title'=>'Mogu li licencu koristiti na nekoliko trgovina?','items'=>['Svaka domena troši jedno mjesto unutar limita paketa i ima vlastitu aktivaciju.']],['title'=>'Podržava li Brendigo Pay pravo naplaćivanje?','items'=>['Trenutačno izdanje je sandbox/testno. Za stvarnu naplatu treba završiti zasebne produkcijske integracije.']],['title'=>'Kako funkcionira naplata bankovnom uplatom?','items'=>['U WooCommerceu koristite zasebni BACS način; ručno potvrdite priljev prije obrade narudžbe.']],['title'=>'Je li Brendigo Pay banka?','items'=>['Ne. To je softverska platforma, a plaćanja izvršavaju vanjski pružatelji.']]],'external'=>[]],'release-checklist'=>['title'=>'Kontrolni popis prije objave','summary'=>'Obavezne provjere prije stvarne web i mobilne produkcije.','sections'=>[['title'=>'Web i dizajn','items'=>['Provjerite sve javne stranice, pravne informacije i kontakt.','Testirajte širine zaslona 320, 375, 768, 1024 i 1440 px te tipkovničku pristupačnost.']],['title'=>'Korisnički i admin panel','items'=>['Provjerite registraciju na webu i Androidu u oba smjera.','Provjerite zabranu čitanja i izmjene tuđih podataka i administratorske ovlasti.']],['title'=>'WordPress','items'=>['Instalirajte dodatak na novoj stranici i napravite nadogradnju preko starog.','Provjerite Classic i Blocks checkout te fail-closed kad nema valjane licence.']],['title'=>'Pružatelji plaćanja','items'=>['Prođite službene testne scenarije svih aktivnih pružatelja, uključujući webhooks i povrate.','Bez uspješnih E2E provjera ne dopuštajte stvarnu naplatu.']],['title'=>'Android i distribucija','items'=>['Provjerite stvarne zaslone na više uređaja.','Potpišite aplikaciju ovlaštenim upload ključem i dovršite Play Console izjave.']]],'external'=>[]]]]];
}

function bp_guide_page(string $path): ?array
{
    $path = rtrim($path, '/');
    $path = $path === '' ? '/' : $path;
    if (!preg_match('#^/(features|integrations|docs)(?:/([a-z][a-z0-9-]*))?$#D', $path, $parts)) {
        return null;
    }
    $catalog = bp_guide_catalog();
    $groupId = $parts[1];
    $slug = $parts[2] ?? '';
    $group = $catalog[$groupId] ?? null;
    if ($group === null) { return null; }
    if ($slug !== '' && !isset($group['pages'][$slug])) { return null; }

    $base = '/' . $groupId;
    $title = $slug === '' ? $group['label'] : $group['pages'][$slug]['title'];
    $summary = $slug === '' ? $group['intro'] : $group['pages'][$slug]['summary'];
    $main = '<div class="bp-guide-breadcrumb"><a href="/">Naslovnica</a><span aria-hidden="true">/</span>';
    if ($slug !== '') {
        $main .= '<a href="' . e($base) . '">' . e($group['label']) . '</a><span aria-hidden="true">/</span>';
    }
    $main .= '<span aria-current="page">' . e($title) . '</span></div>';
    $main .= '<header class="bp-guide-hero"><span class="bp-kicker">' . e($group['kicker'])
        . '</span><h1>' . e($title) . '</h1><p>' . e($summary) . '</p>';
    $main .= '<div class="bp-guide-hero-actions"><a href="/register" class="btn">Odaberi paket →</a>'
        . '<a href="/docs/quickstart" class="btn secondary">Upute za početak</a></div></header>';

    $nav = '<nav class="bp-guide-nav" aria-label="Stranice odjeljka ' . e($group['label']) . '">'
        . '<a class="bp-guide-nav-home' . ($slug === '' ? ' active' : '') . '" href="' . e($base)
        . '">' . e($group['label']) . ' — pregled</a>';
    foreach ($group['pages'] as $key => $item) {
        $nav .= '<a' . ($slug === $key ? ' class="active" aria-current="page"' : '')
            . ' href="' . e($base . '/' . $key) . '">' . e($item['title']) . '</a>';
    }
    $nav .= '</nav>';

    $body = '';
    if ($slug === '') {
        $body .= '<div class="bp-guide-card-grid">';
        foreach ($group['pages'] as $key => $item) {
            $body .= '<a class="bp-guide-card" href="' . e($base . '/' . $key) . '">'
                . '<span class="bp-guide-card-icon" aria-hidden="true">◇</span>'
                . '<strong>' . e($item['title']) . '</strong><p>' . e($item['summary'])
                . '</p><span class="bp-guide-more">Detaljne upute →</span></a>';
        }
        $body .= '</div>';
        if ($groupId === 'features' || $groupId === 'docs') {
            $body .= '<figure class="bp-guide-screenshot"><img loading="lazy" decoding="async"'
                . ' width="1280" height="720" src="/assets/screenshots/user-dashboard-desktop.png"'
                . ' alt="Stvarna lokalna snimka Brendigo Pay korisničke nadzorne ploče">'
                . '<figcaption>Stvarna snimka lokalno pokrenutog testnog korisničkog panela; izgled se može razlikovati od novijeg izdanja.</figcaption></figure>';
        }
    } else {
        $item = $group['pages'][$slug];
        $body .= '<div class="bp-guide-sections">';
        foreach ($item['sections'] as $i => $section) {
            $body .= '<section class="bp-guide-section" id="korak-' . ($i + 1)
                . '"><div class="bp-guide-section-heading"><span aria-hidden="true">'
                . str_pad((string) ($i + 1), 2, '0', STR_PAD_LEFT) . '</span><h2>'
                . e($section['title']) . '</h2></div><ul>';
            foreach ($section['items'] as $bullet) {
                $body .= '<li>' . e($bullet) . '</li>';
            }
            $body .= '</ul></section>';
        }
        if (!empty($item['external'])) {
            $body .= '<section class="bp-guide-resources"><h2>Službeni izvori</h2><ul>';
            foreach ($item['external'] as [$label, $url]) {
                // Keep only official, authored HTTPS destinations.
                if (filter_var($url, FILTER_VALIDATE_URL) && parse_url($url, PHP_URL_SCHEME) === 'https') {
                    $body .= '<li><a href="' . e($url) . '" rel="noopener noreferrer" target="_blank">'
                        . e($label) . '</a></li>';
                }
            }
            $body .= '</ul></section>';
        }
        $body .= '<div class="bp-guide-end"><strong>Treba dodatna pomoć?</strong><p>Provjerite najčešća pitanja ili otvorite upute za rješavanje problema.</p>'
            . '<a class="btn secondary" href="/docs/troubleshooting">Rješavanje problema</a>'
            . '<a class="btn secondary" href="/contact">Kontakt i podrška</a></div>';
    }

    $notice = '<aside class="bp-guide-test-note" role="note"><strong>Testno izdanje.</strong> '
        . 'Stripe, PayPal i Revolut dostupni su samo kroz sandbox integracijske putanje. '
        . 'Stvarne uplate nisu omogućene. Za kupnju ili aktivaciju licence potrebna je provjera '
        . 'plaćenog paketa. Monri i CorvusPay nisu aktivni pružatelji.</aside>';

    $cross = '<nav class="bp-guide-cross" aria-label="Ostale informacije">'
        . '<a href="/features">Mogućnosti</a><a href="/integrations">Integracije</a>'
        . '<a href="/docs">Centar za pomoć</a><a href="/pricing">Cijene</a></nav>';
    return [$title, '<div class="bp-guide-layout"><aside class="bp-guide-sidebar">'
        . '<div class="bp-guide-sidebar-title">Brendigo Pay</div>' . $nav . $cross
        . '</aside><div class="bp-guide-content">' . $main . $notice . $body . '</div></div>'];
}
